35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "membership_points")
85	    private Integer membershipPoints;
86	
87	    @Column(name = "membership_level")
88	    private Integer membershipLevel;
89	
90	    @Column(name = "bulk_signup_warning")
91	    private Boolean bulkSignupWarning;
92	
93	    @Column(name = "possible_duplicate")
94	    private Boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @Column(name = "capacity_warning")
100	    private Boolean capacityWarning;
101	
102	    @Column(name = "deleted", nullable = false)
103	    private boolean deleted;
104	
105	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
106	    private Set<Pet> pets;
107	
108	    public String getTitle() {
109	        return this.title;
110	    }
111	
112	    public void setTitle(String title) {
113	        this.title = title;
114	    }
115	
116	    /**
117	     * The owner's salutation, derived on read from the owner's {@link #title} and last
118	     * name: {@code "<title> <lastName>"} when a title has been supplied, or just the last
119	     * name when it has not.
120	     */
121	    @Transient
122	    public String getSalutation() {
123	        if (this.title == null || this.title.isBlank()) {
124	            return getLastName();
125	        }
126	        return this.title + " " + getLastName();
127	    }
128	
129	    /**
130	     * The owner's canonical API path, formatted {@code /api/owners/<id>}, e.g.
131	     * {@code "/api/owners/1"}. Derived on read from the owner's {@link #getId() id};
132	     * {@code null} until the owner has been persisted and assigned an id.
133	     */
134	    @Transient
135	    public String getSelfLink() {
136	        if (getId() == null) {
137	            return null;
138	        }
139	        return "/api/owners/" + getId();
140	    }
141	
142	    public String getAddress() {
143	        return this.address;
144	    }
145	
146	    public void setAddress(String address) {
147	        this.address = address;
148	    }
149	
150	    /**
151	     * The first line of the owner's structured address, when supplied. Preferred over the
152	     * flat {@link #getAddress() address} and used to compose it; {@code null} for owners
153	     * created from the flat address form.
154	     */
155	    public String getAddressLine1() {
156	        return this.addressLine1;
157	    }
158	
159	    public void setAddressLine1(String addressLine1) {
160	        this.addressLine1 = addressLine1;
161	    }
162	
163	    /**
164	     * The optional second line of the owner's structured address; {@code null} when absent.
165	     * When present it is appended to {@link #getAddressLine1() addressLine1} to compose the
166	     * {@link #getAddress() address}.
167	     */
168	    public String getAddressLine2() {
169	        return this.addressLine2;
170	    }
171	
172	    public void setAddressLine2(String addressLine2) {
173	        this.addressLine2 = addressLine2;
174	    }
175	
176	    public String getCity() {
177	        return this.city;
178	    }
179	
180	    public void setCity(String city) {
181	        this.city = city;
182	    }
183	
184	    public String getTelephone() {
185	        return this.telephone;
186	    }
187	
188	    public void setTelephone(String telephone) {
189	        this.telephone = telephone;
190	    }
191	
192	    /**
193	     * The owner's stored E.164 {@link #telephone} formatted for humans: the country code, a
194	     * space, then the national digits grouped in threes, e.g. {@code "+61 412 345 678"}.
195	     * Derived on read; {@code null} until a telephone has been set.
196	     */
197	    @Transient
198	    public String getTelephoneDisplay() {
199	        return TelephoneDisplay.format(this.telephone);
200	    }
201	
202	    public String getEmail() {
203	        return this.email;
204	    }
205	
206	    public void setEmail(String email) {
207	        this.email = email;
208	    }
209	
210	    public String getPostcode() {
211	        return this.postcode;
212	    }
213	
214	    public void setPostcode(String postcode) {
215	        this.postcode = postcode;
216	    }
217	
218	    public LocalDate getRegistrationDate() {
219	        return this.registrationDate;
220	    }
221	
222	    public void setRegistrationDate(LocalDate registrationDate) {
223	        this.registrationDate = registrationDate;
224	    }
225	
226	    public LocalDate getBirthDate() {
227	        return this.birthDate;
228	    }
229	
230	    public void setBirthDate(LocalDate birthDate) {
231	        this.birthDate = birthDate;
232	    }
233	
234	    /**
235	     * The owner's {@link AgeBand age band} as of their {@link #registrationDate}, derived on
236	     * read from the owner's {@link #birthDate}. {@code null} until both the birth date and the
237	     * registration date have been supplied.
238	     */
239	    @Transient
240	    public String getAgeBand() {
241	        if (this.birthDate == null || this.registrationDate == null) {
242	            return null;
243	        }
244	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
245	    }
246	
247	    public String getCustomerCode() {
248	        return this.customerCode;
249	    }
250	
251	    public void setCustomerCode(String customerCode) {
252	        this.customerCode = customerCode;
253	    }
254	
255	    /**
256	     * The owner's current primary identifier: the single value that identifies the owner
257	     * to the outside world. Today this is the {@link #getCustomerCode() customer code};
258	     * once the customer code is unified into the member id this method will return the
259	     * member id instead, so callers that must carry "the identifier" (such as the owner
260	     * creation audit event) follow the migration automatically.
261	     */
262	    @Transient
263	    public String getPrimaryIdentifier() {
264	        return this.customerCode;
265	    }
266	
267	    /**
268	     * The owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
269	     * digits of the {@link FiscalYear fiscal year} the {@code registrationDate} falls in
270	     * (the fiscal year starts on 1 July), e.g. {@code "FY26"}. Derived on read from the
271	     * owner's registration date; {@code null} until it has been assigned.
272	     */
273	    @Transient
274	    public String getFiscalYear() {
275	        if (this.registrationDate == null) {
276	            return null;
277	        }
278	        return FiscalYear.labelOf(this.registrationDate);
279	    }
280	
281	    /**
282	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
283	     * {@code YY} is the last two digits of the {@link FiscalYear fiscal year} the
284	     * {@code registrationDate} falls in (the fiscal year starts on 1 July), e.g.
285	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
286	     * both the customer code and registration date have been assigned.
287	     */
288	    @Transient
289	    public String getMembershipNumber() {
290	        if (this.customerCode == null || this.registrationDate == null) {
291	            return null;
292	        }
293	        return String.format("%s-M%02d", this.customerCode, FiscalYear.startYearOf(this.registrationDate) % 100);
294	    }
295	
296	    /**
297	     * The owner's check digit: a single {@link Luhn} check digit computed over the digits
298	     * of the owner's {@link #customerCode}. {@code null} until the customer code has been
299	     * assigned.
300	     */
301	    @Transient
302	    public Integer getCheckDigit() {
303	        if (this.customerCode == null) {
304	            return null;
305	        }
306	        return Luhn.checkDigit(this.customerCode);
307	    }
308	
309	    /**
310	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
311	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
312	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
313	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
314	     * segment of the owner's {@link #getCustomerCode() customer code}.
315	     */
316	    @Transient
317	    public String getRegion() {
318	        return RegionPostcodeTable.regionOf(this.postcode)
319	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
320	    }
321	
322	    /**
323	     * The owner's locality, read from its region-and-hash identity: the {@code REGION}
324	     * segment (everything before the first {@code '-'}) of the owner's
325	     * {@link #getCustomerCode() customer code}. Falls back to the owner's live
326	     * {@link #getRegion() region} until a customer code has been assigned.
327	     */
328	    @Transient
329	    public String getLocality() {
330	        if (this.customerCode == null) {
331	            return getRegion();
332	        }
333	        int dash = this.customerCode.indexOf('-');
334	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
335	    }
336	
337	    /**
338	     * The owner's IANA timezone name, derived on read from the owner's
339	     * {@link #getLocality() locality} via the fixed {@link RegionTimezoneTable}, e.g.
340	     * {@code "Australia/Sydney"} for {@code NSW}. {@code null} when the locality has no
341	     * timezone in the table.
342	     */
343	    @Transient
344	    public String getTimezone() {
345	        return RegionTimezoneTable.timezoneOf(getLocality());
346	    }
347	
348	    /**
349	     * The owner's preferred contact channel, derived on read from the owner's own
350	     * fields: {@code "EMAIL"} when the owner has an email address, otherwise
351	     * {@code "PHONE"}.
352	     */
353	    @Transient
354	    public String getContactPreference() {
355	        return (this.email == null || this.email.isBlank()) ? "PHONE" : "EMAIL";
356	    }
357	
358	    /**
359	     * The owner's identity key: the single value used to detect duplicate owners on
360	     * create. It is the lower-case SHA-256 hex digest of the owner's (already normalized)
361	     * telephone, lower-cased email and the {@link Soundex} code of its last name, joined
362	     * with {@code '|'} — {@code sha256(<telephone>|<lowerEmail>|<soundex(lastName)>)} — a
363	     * missing telephone or email contributing an empty segment. Two owners are duplicates
364	     * only when their whole identity keys are equal.
365	     */
366	    @Transient
367	    public String getIdentityKey() {
368	        String normalizedTelephone = orEmpty(this.telephone);
369	        String lowerEmail = orEmpty(this.email).toLowerCase(Locale.ROOT);
370	        String lastNameSoundex = Soundex.encode(getLastName());
371	        return Sha256Hex.hex(normalizedTelephone + "|" + lowerEmail + "|" + lastNameSoundex);
372	    }
373	
374	    private static String orEmpty(String value) {
375	        return value == null ? "" : value;
376	    }
377	
378	    public String getHouseholdId() {
379	        return this.householdId;
380	    }
381	
382	    public void setHouseholdId(String householdId) {
383	        this.householdId = householdId;
384	    }
385	
386	    public Integer getNamesakeCount() {
387	        return this.namesakeCount;
388	    }
389	
390	    public void setNamesakeCount(Integer namesakeCount) {
391	        this.namesakeCount = namesakeCount;
392	    }
393	
394	    public Integer getHouseholdSize() {
395	        return this.householdSize;
396	    }
397	
398	    public void setHouseholdSize(Integer householdSize) {
399	        this.householdSize = householdSize;
400	    }
401	
402	    /**
403	     * The owner's membership points, assigned on create by tallying the owner's standing:
404	     * points for having an email address, for having no namesakes, for a large household and
405	     * for tenure (see {@code MembershipLevelAssigner}). The points determine the owner's
406	     * {@link #getMembershipLevel() membership level}.
407	     */
408	    public Integer getMembershipPoints() {
409	        return this.membershipPoints;
410	    }
411	
412	    public void setMembershipPoints(Integer membershipPoints) {
413	        this.membershipPoints = membershipPoints;
414	    }
415	
416	    /**
417	     * The owner's membership level, a number from 1 to 4 assigned on create by banding the
418	     * owner's {@link #getMembershipPoints() membership points} (see
419	     * {@code MembershipLevelAssigner}).
420	     */
421	    public Integer getMembershipLevel() {
422	        return this.membershipLevel;
423	    }
424	
425	    public void setMembershipLevel(Integer membershipLevel) {
426	        this.membershipLevel = membershipLevel;
427	    }
428	
429	    public Boolean getBulkSignupWarning() {
430	        return this.bulkSignupWarning;
431	    }
432	
433	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
434	        this.bulkSignupWarning = bulkSignupWarning;
435	    }
436	
437	    /**
438	     * Whether this owner, when created, softly matched an already-stored owner: one whose
439	     * last name shares its {@link Soundex} code and whose postcode matches, while their
440	     * {@link #getIdentityKey() identity keys} differ. Assigned on create; when {@code true},
441	     * {@link #getPossibleDuplicateOf()} identifies the matched owner.
442	     */
443	    public Boolean getPossibleDuplicate() {
444	        return this.possibleDuplicate;
445	    }
446	
447	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
448	        this.possibleDuplicate = possibleDuplicate;
449	    }
450	
451	    /**
452	     * The id of the already-stored owner this owner softly matched on create (matching
453	     * last-name Soundex and postcode, differing identity key), or {@code null} when it
454	     * matched none.
455	     */
456	    public Integer getPossibleDuplicateOf() {
457	        return this.possibleDuplicateOf;
458	    }
459	
460	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
461	        this.possibleDuplicateOf = possibleDuplicateOf;
462	    }
463	
464	    /**
465	     * Whether this owner's city was approaching its owner capacity when the owner was
466	     * created: {@code true} when the city already held between 40 and 49 owners (the hard
467	     * limit is 50), otherwise {@code false}. Assigned on create.
468	     */
469	    public Boolean getCapacityWarning() {
470	        return this.capacityWarning;
471	    }
472	
473	    public void setCapacityWarning(Boolean capacityWarning) {
474	        this.capacityWarning = capacityWarning;
475	    }
476	
477	    /**
478	     * Whether this owner has been soft-deleted. A newly created owner is {@code false};
479	     * {@code DELETE /api/owners/{id}} flags it {@code true} while retaining the record. Owners
480	     * flagged deleted are ignored by the create endpoint's duplicate and identity checks.
481	     */
482	    public boolean isDeleted() {
483	        return this.deleted;
484	    }
485	
486	    public void setDeleted(boolean deleted) {
487	        this.deleted = deleted;
488	    }
489	
490	    protected Set<Pet> getPetsInternal() {
491	        if (this.pets == null) {
492	            this.pets = new HashSet<>();
493	        }
494	        return this.pets;
495	    }
496	
497	    protected void setPetsInternal(Set<Pet> pets) {
498	        this.pets = pets;
499	    }
500	
501	    public List<Pet> getPets() {
502	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
503	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
504	        return Collections.unmodifiableList(sortedPets);
505	    }
506	
507	    public void setPets(List<Pet> pets) {
508	        this.pets = new HashSet<>(pets);
509	    }
510	
511	    public void addPet(Pet pet) {
512	        getPetsInternal().add(pet);
513	        pet.setOwner(this);
514	    }
515	
516	    /**
517	     * Return the Pet with the given name, or null if none found for this Owner.
518	     *
519	     * @param name to test
520	     * @return true if pet name is already in use
521	     */
522	    public Pet getPet(String name) {
523	        return getPet(name, false);
524	    }
525	
526	    /**
527	     * Return the Pet with the given name, or null if none found for this Owner.
528	     *
529	     * @param name to test
530	     * @return true if pet name is already in use
531	     */
532	    public Pet getPet(String name, boolean ignoreNew) {
533	        name = name.toLowerCase();
534	        for (Pet pet : getPetsInternal()) {
535	            if (!ignoreNew || !pet.isNew()) {
536	                String compName = pet.getName();
537	                compName = compName.toLowerCase();
538	                if (compName.equals(name)) {
539	                    return pet;
540	                }
541	            }
542	        }
543	        return null;
544	    }
545	
546	    public Pet getPet(Integer petId) {
547	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
548	    }
549	
550	    @Override
551	    public String toString() {
552	        return new ToStringCreator(this)
553	
554	            .append("id", this.getId())
555	            .append("new", this.isNew())
556	            .append("lastName", this.getLastName())
557	            .append("firstName", this.getFirstName())
558	            .append("address", this.address)
559	            .append("city", this.city)
560	            .append("telephone", this.telephone)
561	            .append("email", this.email)
562	            .append("registrationDate", this.registrationDate)
563	            .append("customerCode", this.customerCode)
564	            .toString();
565	    }
566	}
